ROWS = []
for key, (status, supports, use, todo) in N.items():
    r = R.get(key) or dict(doi="10.2307/4615733", registry="index record only (OpenAlex): author, title, journal, year, volume, pages", year_print="1979", year_issued="1979", title="", container="", vol="", issue="", page_openalex="", page_crossref="")
    au = []
    p = CACHE / f"crossref_{key}.json"
    cr = json.load(open(p)) if p.exists() else {}
    for a in cr.get("author", []):
        au.append(f"{a.get('family', '')}, {''.join(x[0] + '.' for x in a.get('given', '').replace('-', ' ').split())}")
    if key == "hansen2011":
        au = ["Hansen, P.R.", "Lunde, A.", "Nason, J.M."]
    yr = {"santos2013": 2013, "brooks2003": 2003}.get(key) or r["year_print"] or r["year_issued"]
    cit = f"{'; '.join(au)} ({yr}). {r['title']}. {r['container']} {r['vol']}({r['issue']}), {r['page_openalex'] or r['page_crossref']}."
    if key == "holm1979":
        cit = "Holm, S. (1979). A simple sequentially rejective multiple test procedure. Scandinavian Journal of Statistics 6, 65-70."
    cit = html.unescape(cit)
    ROWS.append(dict(citation=cit.replace("()", "").replace("(,", "("), research_question="", data="", method="", evaluation_design="", main_result=supports, assumptions="",
                     limitations="", relevance_to_thesis=use, what_i_need_to_extract=todo, reading_status=status, doi=r["doi"],
                     registry_check=r["registry"] if key != "hansen2011" else "MATCH on title, venue, year, volume, issue, pages; authors from RePEc", retrieved=TODAY))
